llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Elbasvir, the closest structural analogue (Morgan similarity 0.6098), has an absolute oral bioavailability of approximately 32% in HCV-infected subjects, directly supporting F ≥ 20% for this large NS5A-inhibitor chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Ledipasvir, another closely related large NS5A inhibitor, shows about 53% oral bioavailability in humans, reinforcing that high-molecular-weight, lipophilic members of this class can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest experimental analogues, elbasvir (F ≈ 32%) and ledipasvir (F ≈ 53%), provide direct human bioavailability measurements in the same large NS5A-inhibitor chemical class and support F ≥ 20%, overriding the uncertain physicochemical prior that predicted low bioavailability.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "Elbasvir's reported range (20–40%) has its lower bound at the threshold, so the exact margin is uncertain.",
    "The query's biphenyl core differs from elbasvir's benzofuran and ledipasvir's fluorene cores; effects on absorption or efflux are not directly measured.",
    "Solubility and dissolution behavior of the query in human gastrointestinal conditions are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

